Read file .omgithub/scripts/live-files/server.mjs, lines 1-76
1: import { createServer } from 'vite'
2: import serveIndex from 'serve-index'
3: import { stat, readFile } from 'node:fs/promises'
4: import { resolve, relative, isAbsolute, extname, join } from 'node:path'
5: import { pathToFileURL } from 'node:url'
6: 
7: const textExtensions = new Set(['.md', '.markdown', '.sh', '.bash', '.zsh', '.fish', '.log'])
8: 
9: export function directoryBrowser(root) {
10:   const listing = serveIndex(root, { icons: true, view: 'details' })
11:   return {
12:     name: 'omgithub-directory-browser',
13:     configureServer(server) {
14:       server.middlewares.use(async (req, res, next) => {
15:         if (req.method !== 'GET' && req.method !== 'HEAD') return next()
16:         try {
17:           const url = new URL(req.url, 'http://localhost')
18:           const file = resolve(root, '.' + decodeURIComponent(url.pathname))
19:           const within = relative(root, file)
20:           if (within.startsWith('..') || isAbsolute(within)) return next()
21:           const info = await stat(file)
22:           res.setHeader('Cache-Control', 'no-cache')
23:           if (info.isDirectory()) {
24:             if (!url.pathname.endsWith('/')) {
25:               res.writeHead(302, { Location: url.pathname + '/' + url.search }); res.end(); return
26:             }
27:             return listing(req, res, next)
28:           }
29:           // Keep document/source browsing readable; leave browser modules to Vite.
30:           if (textExtensions.has(extname(file)) && !url.searchParams.has('import') && !url.searchParams.has('raw')) {
31:             res.setHeader('Content-Type', 'text/plain; charset=utf-8')
32:             res.end(req.method === 'HEAD' ? undefined : await readFile(file)); return
33:           }
34:           next()
35:         } catch (error) {
36:           if (error.code === 'ENOENT' || error.code === 'ENOTDIR') return next()
37:           next(error)
38:         }
39:       })
40:     }
41:   }
42: }
43: 
44: export async function startLiveFiles({ root, port = 0, cacheDir, allowedHosts = [] } = {}) {
45:   root = resolve(root)
46:   const server = await createServer({
47:     // Start before the agent creates package.json/config/dependencies. Keep this
48:     // managed source browser independent of project build and startup scripts.
49:     configFile: false,
50:     root,
51:     base: '/',
52:     appType: 'mpa',
53:     cacheDir,
54:     plugins: [directoryBrowser(root)],
55:     server: {
56:       host: '127.0.0.1', port, strictPort: true,
57:       allowedHosts,
58:       headers: { 'Cache-Control': 'no-cache' }
59:     }
60:   })
61:   await server.listen()
62:   return server
63: }
64: 
65: if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
66:   const started = performance.now()
67:   const server = await startLiveFiles({
68:     root: process.env.PROJECT_DIR,
69:     port: Number(process.env.PROJECT_FILE_PORT),
70:     cacheDir: join(process.env.OPENCODE_WEB_DIR, 'live-vite-cache'),
71:     allowedHosts: ['.omgithub.com', '.lolgames.net']
72:   })
73:   console.error(`[timing] live source server startup: ${Math.round(performance.now() - started)} ms`)
74:   server.printUrls()
75:   for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, async () => { await server.close(); process.exit(0) })
76: }

